/**
 * Regenerates the curriculum index from the subject files already on disk.
 *
 * Why this exists: `build.ts` writes each subject file as it finishes, but only rewrites
 * `data/index.ts` after the very last subject. A run that is interrupted, or still going,
 * therefore leaves perfectly good subject data invisible to the app. This rebuilds the
 * index from whatever files exist, so partial progress is never wasted or silent.
 *
 *   node --import tsx scripts/curriculum/reindex.ts
 *
 * It reads the `code` and `name` out of each generated file, so it never guesses which
 * subjects are real: a file only counts when it declares `SubjectCurriculum`.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const DATA_DIR = path.join(ROOT, 'src/shared/curriculum/data');
const INDEX_FILE = path.join(DATA_DIR, 'index.ts');

const log = (...parts: unknown[]) => console.log('[curriculum:index]', ...parts);

interface Found {
  code: string;
  name: string;
  file: string;
  /** Exported constant name, e.g. GSCI_CURRICULUM. */
  constant: string;
  topics: number;
}

/** Count `"topic":` occurrences: a cheap, honest size check without importing. */
function countTopics(text: string): number {
  return (text.match(/"topic":/g) ?? []).length;
}

function discover(): Found[] {
  const found: Found[] = [];
  for (const entry of fs.readdirSync(DATA_DIR)) {
    if (!entry.endsWith('.ts') || entry === 'index.ts') continue;

    const file = path.join(DATA_DIR, entry);
    const text = fs.readFileSync(file, 'utf8');

    // Only files produced by the builder, so a hand-written file is never adopted.
    if (!/Generated by scripts\/curriculum\/build\.ts/.test(text)) {
      log(`skip ${entry}: not generated by the builder`);
      continue;
    }
    if (!/SubjectCurriculum/.test(text)) {
      log(`skip ${entry}: does not declare a SubjectCurriculum`);
      continue;
    }

    const code = /code:\s*"([A-Z0-9_]+)"/.exec(text)?.[1];
    const name = /name:\s*"([^"]+)"/.exec(text)?.[1];
    const constant = new RegExp(`export const ([A-Z0-9_]+_CURRICULUM)`).exec(text)?.[1];

    if (!code || !constant) {
      log(`skip ${entry}: could not read its code/constant`);
      continue;
    }
    found.push({ code, name: name ?? code, file: entry, constant, topics: countTopics(text) });
  }

  // Stable, readable order: core subjects first, then electives — driven by the
  // catalog rather than by filename, so the index is deterministic between runs.
  return found.sort((a, b) => a.file.localeCompare(b.file));
}

async function main() {
  const found = discover();
  if (found.length === 0) {
    log('no subject files found; leaving index.ts untouched');
    return;
  }

  // The version must change whenever the CONTENT changes, or caches keep serving old
  // sets. Hash the file contents, so a re-run with identical data is a no-op for caches.
  const crypto = await import('node:crypto');
  const hash = crypto.createHash('sha256');
  for (const item of found) {
    hash.update(item.file);
    hash.update(fs.readFileSync(path.join(DATA_DIR, item.file)));
  }
  const digest = hash.digest('hex').slice(0, 8);
  const version = `${new Date().toISOString().slice(0, 10)}+${digest}`;

  // The data files are imported ONLY by the lazy per-subject loaders in
  // shared/curriculum/index.ts. The index itself carries metadata only, so a phone
  // never downloads every subject's topics to render a picker.
  const meta = found
    .map((f) => `  { code: ${JSON.stringify(f.code)}, name: ${JSON.stringify(f.name)} }`)
    .join(',\n');

  fs.writeFileSync(
    INDEX_FILE,
    `// Generated by scripts/curriculum/reindex.ts — do not edit by hand.\n` +
      `/** Code + name for every subject with curriculum data in this build. */\n` +
      `export interface CurriculumSubjectMeta { code: string; name: string }\n\n` +
      `/** Cache-busting version of the curriculum data (date + content digest). */\n` +
      `export const GENERATED_VERSION = ${JSON.stringify(version)};\n\n` +
      `export const GENERATED_CURRICULUM: CurriculumSubjectMeta[] = [\n${meta}\n];\n`
  );

  log(`indexed ${found.length} subject(s), version ${version}`);
  for (const f of found) log(`  ${f.code.padEnd(7)} ${String(f.topics).padStart(3)} topic(s)  ${f.name}`);
}

main().catch((err) => {
  console.error('[curriculum:index] failed:', err);
  process.exitCode = 1;
});
